type PageId = "dashboard" | "profile" | "plans" | "verification" | "tournaments" | "training" | "medals" | "documents" | "weight" | "calendar" | "checklist" | "scanner" | "ai" | "feedback" | "roadmap" | "messages" | "taekwondo" | "admin";
type ToastState = { type: "success" | "error" | "warning"; message: string } | null;
type AdminRole = "support_admin" | "admin" | "super_admin";
type AuthMode = "login" | "register" | "forgot" | "reset";
const adminRoles = new Set<AdminRole>(["support_admin", "admin", "super_admin"]);
const nav: Array<[PageId, string, typeof Activity]> = [["dashboard", "Dashboard", Activity],["taekwondo", "Taekwondo", Activity],["messages", "Messages", MessageCircle],["profile", "Profile", User],["plans", "Plans", CreditCard],["verification", "Verification", BadgeCheck],["tournaments", "Tournaments", Trophy],["training", "Training", Calendar],["calendar", "Calendar", Calendar],["medals", "Medals", Medal],["documents", "Documents", FolderLock],["weight", "Weight", Weight],["checklist", "Checklist", CheckCircle2],["scanner", "Scanner", ScanLine],["ai", "AI Coach", Sparkles],["feedback", "Feedback", HeartPulse],["roadmap", "Roadmap", Target],["admin", "Admin", Gauge]];
function isAdminProfile(profile: Profile) { return adminRoles.has(profile.role as AdminRole); }
function isPasswordResetRoute() { return window.location.pathname === "/reset-password"; }
function isAuthCallbackRoute() { return window.location.pathname === "/auth/callback"; }
const pageRoutes: Record<string, PageId> = { "/": "dashboard", "/profile": "profile", "/plans": "plans", "/verification": "verification", "/tournaments": "tournaments", "/training": "training", "/medals": "medals", "/documents": "documents", "/weight": "weight", "/calendar": "calendar", "/checklist": "checklist", "/scanner": "scanner", "/ai": "ai", "/feedback": "feedback", "/roadmap": "roadmap", "/messages": "messages", "/taekwondo": "taekwondo", "/admin": "admin" };
function pageFromPath(): PageId { return pageRoutes[window.location.pathname] || "dashboard"; }
function sanitizeProfileValues(values: Partial<Profile>) { const safeValues: Partial<Profile> = {}; const allowedKeys: Array<keyof Profile> = ["full_name","username","date_of_birth","gender","sport","discipline","profile_image_path","weight_kg","height_cm","belt","academy","coach","emergency_contact","achievements"]; for (const key of allowedKeys) if (values[key] !== undefined) safeValues[key] = values[key] as never; if (!safeValues.full_name?.trim()) throw new Error("Full name is required to complete onboarding."); safeValues.full_name = safeValues.full_name.trim(); if (safeValues.username !== undefined) { const username = String(safeValues.username).trim().toLowerCase(); if (username && !/^[a-z0-9][a-z0-9_.-]{2,29}$/.test(username)) throw new Error("Username must be 3–30 characters and use lowercase letters, numbers, dots, underscores, or hyphens."); safeValues.username = username || undefined; } return safeValues; }
function Field({ label, ...props }: React.InputHTMLAttributes<HTMLInputElement> & { label: string }) { return <label className="field"><span>{label}{props.required ? " *" : ""}</span><input {...props} /></label>; }
function SelectField({ label, children, ...props }: React.SelectHTMLAttributes<HTMLSelectElement> & { label: string }) { return <label className="field"><span>{label}{props.required ? " *" : ""}</span><select {...props}>{children}</select></label>; }
function Toast({ toast, onClear }: { toast: ToastState; onClear: () => void }) { useEffect(() => { if (!toast || toast.type !== "error") return; const timer = window.setTimeout(onClear, 10000); return () => window.clearTimeout(timer); }, [toast, onClear]); if (!toast || toast.type !== "error") return null; return <div className="toast error" role="alert">{toast.message}</div>; }
function VerificationCallback() { const auth = useAuth(); const params = new URLSearchParams(window.location.search); const errorDescription = params.get("error_description") || params.get("error"); useEffect(() => { if (auth.user) { const target = auth.emailVerified ? "/" : "/onboarding"; window.history.replaceState(null, "", target); } }, [auth.user, auth.emailVerified]); if (errorDescription) return <main className="auth-page"><section className="auth-card"><span className="eyebrow">AthleteN verification</span><h1>Verification link could not be used</h1><p>The link may be expired, already used, or malformed. Return to login and request a new verification email if needed.</p><p className="notice" role="alert">{errorDescription.includes("expired") ? "This verification link has expired." : "Email verification could not be completed."}</p></section></main>; return <main className="auth-page"><section className="auth-card"><span className="eyebrow">AthleteN verification</span><h1>{auth.emailVerified ? "Email verified" : "Finishing verification..."}</h1><p>{auth.emailVerified ? "Your email is verified. Redirecting you back to AthleteN." : "Please wait while AthleteN confirms your email session."}</p></section></main>; }
function AuthScreen({ initialMode }: { initialMode?: AuthMode }) { const auth = useAuth(); const [mode, setMode] = useState<AuthMode>(initialMode || (isPasswordResetRoute() ? "reset" : "login")); const [form, setForm] = useState({ email: "", password: "", name: "" }); const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false); async function submit(event: React.FormEvent) { event.preventDefault(); setMessage(""); setBusy(true); try { if (mode === "register") { await auth.signUp({ email: form.email, password: form.password, metadata: { full_name: form.name } }); setMessage("Check your email for the AthleteN verification link. After verifying, you will return here automatically."); } else if (mode === "forgot") { await auth.resetPassword(form.email); setMessage("Password reset email sent."); } else if (mode === "reset") { await auth.updatePassword(form.password); setMessage("Password updated. You can continue to AthleteN."); window.history.replaceState(null, "", "/"); setMode("login"); } else await auth.signIn({ email: form.email, password: form.password }); } catch (error) { setMessage(error instanceof Error ? error.message : "Authentication failed."); } finally { setBusy(false); } } async function resendVerification() { if (!form.email.trim()) { setMessage("Enter your email address first."); return; } setBusy(true); try { await auth.resendVerification(form.email); setMessage("A new AthleteN verification email has been sent."); } catch (error) { setMessage(error instanceof Error ? error.message : "Verification email could not be resent."); } finally { setBusy(false); } } async function signInWithGoogle() { setMessage(""); setBusy(true); try { await auth.signInWithGoogle(); setMessage("Redirecting to Google sign-in..."); } catch (error) { setMessage(error instanceof Error ? error.message : "Google sign-in could not be started."); setBusy(false); } } if (!auth.configured) { const configurationIssues = supabaseConfig.missing.concat(supabaseConfig.invalid); return <main className="auth-page"><section className="auth-card"><h1>AthleteN</h1><p>Supabase is not configured. Add the required public Vite variables to run the cloud app.</p>{configurationIssues.length > 0 && <p className="notice" role="status">Missing or invalid: {configurationIssues.join(", ")}</p>}</section></main>; } return <main className="auth-page"><section className="auth-card"><span className="eyebrow">Nova Code</span><h1>AthleteN - Taekwondo Edition</h1><p>Secure cloud command center for training, tournaments, documents, medals, goals, verification, plans, and AI coaching.</p><button type="button" className="btn oauth-btn" onClick={() => void signInWithGoogle()} disabled={busy}>Continue with Google</button><div className="oauth-divider"><span>or use email</span></div><form onSubmit={submit}>{mode === "register" && <Field label="Name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required />}{mode !== "reset" && <Field label="Email" type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} required />}{mode !== "forgot" && <Field label="Password" type="password" minLength={8} value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} required />}<label className="remember"><input type="checkbox" defaultChecked /> Remember me on this device</label><button className="btn primary" disabled={busy}>{busy ? "Please wait..." : mode === "register" ? "Create account" : mode === "forgot" ? "Send reset email" : mode === "reset" ? "Update password" : "Log in"}</button></form>{message && <p className="notice" role="status">{message}</p>}<div className="auth-links"><button type="button" onClick={() => { setMessage(""); setMode("login"); }}>Login</button><button type="button" onClick={() => { setMessage(""); setMode("register"); }}>Register</button><button type="button" onClick={() => { setMessage(""); setMode("forgot"); }}>Forgot password</button>{mode === "register" && <button type="button" onClick={resendVerification} disabled={busy}>Resend verification</button>}{mode === "reset" && <button type="button" onClick={() => { setMessage(""); setMode("reset"); }}>Reset password</button>}</div></section></main>; }
function Stat({ icon: Icon, label, value, note }: { icon: typeof Activity; label: string; value: string | number; note: string }) { return <article className="metric card"><div className="metric-icon"><Icon size={18} /></div><div><p>{label}</p><strong>{value}</strong><small>{note}</small></div></article>; }
function DataTable<T extends { id?: string }>({ rows, columns, empty }: { rows: T[]; empty: string; columns: Array<{ key: string; label: string; render?: (row: T) => React.ReactNode }> }) { if (!rows.length) return <div className="empty"><strong>{empty}</strong><p>Add a record with the action above.</p></div>; return <div className="table-wrap"><table><thead><tr>{columns.map((col) => <th key={col.key}>{col.label}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={row.id ?? index}>{columns.map((col) => <td key={col.key}>{col.render ? col.render(row) : String((row as Record<string, unknown>)[col.key] ?? "")}</td>)}</tr>)}</tbody></table></div>; }
function useCloudData(userId: string | undefined, setToast: (toast: ToastState) => void) { const [data, setData] = useState<CloudData>({ profile: {}, tournaments: [], training: [], medals: [], weights: [], goals: [], checklist: [], documents: [], notifications: [], feedback: [], verifications: [], roadmap: [], roadmapVotes: [], tournamentScans: [], aiUsage: [], subscriptions: [], subscriptionUsage: [] }); const [hasProfile, setHasProfile] = useState(false); const [loading, setLoading] = useState(true); async function refresh() { if (!userId || !isSupabaseConfigured) return; setLoading(true); const dataErrors: string[] = []; async function loadUserRows<T>(resource: Resource, options: { order?: string; ascending?: boolean } = {}) { try { return await listRows<T>(resource, userId, options); } catch (error) { dataErrors.push(error instanceof Error ? error.message : `Unable to load ${resource}.`); return [] as T[]; } } try { const profiles = await listRows<Profile>("profile", userId); const savedProfile = profiles[0]; const profileComplete = Boolean(savedProfile?.full_name?.trim()); const profile = savedProfile || { user_id: userId, plan_id: "free", role: "athlete" }; const [tournaments, training, medals, weights, goals, checklist, documents, notifications, feedback, verifications, roadmapRows, roadmapVotes, tournamentScans, aiUsage, subscriptions, subscriptionUsage, kyorugiBouts, poomsaePerformances, taekwondoTraining] = await Promise.all([loadUserRows<Tournament>("tournaments", { order: "starts_at", ascending: true }), loadUserRows<TrainingSession>("training", { order: "session_date", ascending: false }), loadUserRows<MedalRecord>("medals", { order: "awarded_at", ascending: false }), loadUserRows<WeightLog>("weights", { order: "logged_at", ascending: true }), loadUserRows<Goal>("goals", { order: "target_date", ascending: true }), loadUserRows<ChecklistItem>("checklist"), loadUserRows<DocumentRecord>("documents", { order: "created_at" }), loadUserRows<{ id?: string; title: string; body?: string; read_at?: string }>("notifications", { order: "created_at" }), loadUserRows<FeedbackItem>("feedback", { order: "created_at" }), loadUserRows<VerificationRequest>("verifications", { order: "created_at" }), listRows<RoadmapItem>("roadmap", undefined, { order: "votes", publicRows: true }).catch((error) => { dataErrors.push(error instanceof Error ? error.message : "Unable to load roadmap."); return [] as RoadmapItem[]; }), loadUserRows<RoadmapVote>("roadmapVotes", { order: "created_at" }), loadUserRows<TournamentScan>("tournamentScans", { order: "last_checked_at", ascending: false }), loadUserRows<AiUsageEvent>("aiUsage", { order: "created_at", ascending: false }), loadUserRows<Subscription>("subscriptions", { order: "created_at", ascending: false }), loadUserRows<SubscriptionUsage>("subscriptionUsage", { order: "usage_month", ascending: false }), loadUserRows<KyorugiBout>("kyorugiBouts", { order: "event_date", ascending: false }), loadUserRows<PoomsaePerformance>("poomsaePerformances", { order: "event_date", ascending: false }), loadUserRows<TaekwondoTrainingLog>("taekwondoTraining", { order: "session_date", ascending: false })]); setHasProfile(profileComplete); setData({ profile, tournaments, training, medals, weights, goals, checklist, documents, notifications, feedback, verifications, roadmap: roadmapRows.map((item) => ({ ...item, user_has_voted: roadmapVotes.some((vote) => vote.roadmap_item_id === item.id) })), roadmapVotes, tournamentScans, aiUsage, subscriptions, subscriptionUsage, kyorugiBouts, poomsaePerformances, taekwondoTraining }); if (dataErrors.length > 0) setToast({ type: "warning", message: dataErrors.slice(0, 2).join(" ") }); } catch (error) { setHasProfile(false); setToast({ type: "error", message: error instanceof Error ? error.message : "Unable to load profile." }); } finally { setLoading(false); } } useEffect(() => { void refresh(); }, [userId]); return { data, loading, refresh, hasProfile }; }
function FeaturePage({ title, actions, children }: { title: string; actions?: React.ReactNode; children: React.ReactNode }) { return <><div className="page-head"><div><p className="eyebrow">AthleteN V2</p><h2>{title}</h2></div>{actions}</div>{children}</>; }
function documentStatus(expiresAt?: string) { if (!expiresAt) return { label: "Valid", tone: "success" }; const today = new Date(); const expiry = new Date(`${expiresAt}T00:00:00`); const days = Math.ceil((expiry.getTime() - today.getTime()) / 86400000); if (days < 0) return { label: "Expired", tone: "error" }; if (days <= 30) return { label: "Expiring soon", tone: "warning" }; return { label: "Valid", tone: "success" }; }
function Dashboard({ data, usage, openForm }: { data: CloudData; usage: UsageSummary; openForm: (resource: Resource) => void }) { const role = data.profile.role; const planId = data.profile.plan_id; if (role === "coach" || planId === "champion") return <CoachDashboard profile={data.profile} userId={data.profile.user_id} setToast={() => undefined} />; if (role === "academy_admin" || planId === "academy") return <AcademyDashboard profile={data.profile} userId={data.profile.user_id} setToast={() => undefined} />; const latestWeight = data.weights.at(-1)?.weight_kg || data.profile.weight_kg || 0; const readiness = calculateReadiness(data); return <><AthleteCommandCenter data={data} /><section className="hero card"><div><span className="pill">Taekwondo Edition V2</span><h2>Train, compete, verify, and grow.</h2><p>Cloud-backed athlete operating system with protected routes, Supabase RLS, plan limits, student verification, and server-side AI.</p><div className="hero-actions"><button className="btn primary" onClick={() => openForm("training")}>Log training</button><button className="btn" onClick={() => openForm("tournaments")}>Add tournament</button></div></div><div className="readiness"><strong>{readiness}%</strong><span>Readiness</span></div></section><section className="metrics"><Stat icon={Trophy} label="Tournaments" value={data.tournaments.length} note="Tracked events" /><Stat icon={Calendar} label="Training" value={data.training.length} note="Sessions logged" /><Stat icon={Weight} label="Weight" value={`${latestWeight} kg`} note="Latest log" /><Stat icon={Sparkles} label="AI usage" value={`${usage.used}/${usage.limit}`} note={usage.plan.name} /></section><section className="grid two"><article className="card panel"><h3>Weight trend</h3><ResponsiveContainer width="100%" height={220}><LineChart data={data.weights}><CartesianGrid strokeDasharray="3 3" stroke="#25405f" /><XAxis dataKey="logged_at" /><YAxis /><Tooltip /><Line type="monotone" dataKey="weight_kg" stroke="#49d7ff" strokeWidth={3} /></LineChart></ResponsiveContainer></article><article className="card panel"><h3>Goals</h3>{data.goals.map((goal) => <div className="goal" key={goal.id || goal.title}><span>{goal.title}</span><b>{goal.progress || 0}%</b><i style={{ width: `${goal.progress || 0}%` }} /></div>)}</article></section></>; }
function PlansPage({ profile, userId, onSaved, onToast }: { profile: Profile; userId: string; onSaved: () => Promise<void>; onToast: (toast: ToastState) => void }) { const currentPlan = getPlan(profile.plan_id || "free"); const [trialBusy, setTrialBusy] = useState(false); const [trialUsed, setTrialUsed] = useState(Boolean((profile as Profile & { trial_used?: boolean }).trial_used)); async function startTrial(planId: Exclude<PlanId, "free">) { if (!userId || trialBusy || trialUsed) return; setTrialBusy(true); onToast(null); try { const now = new Date(); const end = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); const { data: existing, error: existingError } = await supabase.from("subscriptions").select("id,status,current_period_end").eq("user_id", userId).in("status", ["active","trialing"]).order("created_at", { ascending: false }).limit(1); if (existingError) throw existingError; const active = existing?.[0]; if (active?.status === "active") throw new Error("You already have an active plan. A trial cannot be started while an active plan is assigned."); if (active?.status === "trialing" && active.current_period_end && new Date(active.current_period_end) > now) throw new Error("A trial is already active on this account."); const { error: subError } = await supabase.from("subscriptions").insert({ user_id: userId, plan_id: planId, provider: "manual", status: "trialing", current_period_end: end.toISOString() }); if (subError) throw subError; const { error: profileError } = await supabase.from("profiles").update({ plan_id: planId, trial_used: true }).eq("user_id", userId); if (profileError) throw profileError; setTrialUsed(true); await onSaved(); } catch (error) { onToast({ type: "error", message: error instanceof Error ? error.message : "Trial could not be started." }); } finally { setTrialBusy(false); } } return <FeaturePage title="Plans and billing"><section className="card panel billing-note"><CreditCard /><div><p className="eyebrow">Your membership</p><h3>Current plan: {currentPlan.name}</h3><p>Choose the plan that matches your training needs. Prices and AI allowances are shown directly from the AthleteN plan configuration.</p></div><span className="status-chip success">Active</span></section><section className="card panel"><div className="inline-actions"><Star size={18} /><div><h3>7-day trial</h3><p>Try any paid AthleteN plan for 7 days. The trial is recorded as trialing and does not start online checkout.</p></div></div></section><section className="plan-grid" aria-label="AthleteN plans">{plans.map((plan) => { const isCurrent = plan.id === currentPlan.id; const paidPlan = plan.id !== "free"; return <article className={`card plan-card ${isCurrent ? "active" : ""}`} key={plan.id}><div className="plan-card-head"><span className="pill">{plan.audience}</span>{isCurrent && <span className="status-chip success">Current</span>}</div><h3>{plan.name}</h3><div className="plan-price" aria-label={`${plan.name} price`}><strong>{plan.price}</strong></div><p className="plan-ai">{plan.aiLimit.toLocaleString()} AI coach messages/month</p><ul>{plan.features.map((feature) => <li key={feature}>{feature}</li>)}</ul>{isCurrent ? <button className="btn" disabled>Current plan</button> : paidPlan ? <div className="plan-actions">{!trialUsed && <button className="btn primary" type="button" onClick={() => void startTrial(plan.id as Exclude<PlanId, "free">)} disabled={trialBusy}>Start 7-day trial</button>}<button className="btn" type="button" disabled>Choose plan</button></div> : <button className="btn" disabled>Free plan</button>}</article>; })}</section><section className="card panel"><div className="inline-actions"><Shield size={18} /><div><h3>Secure billing status</h3><p>Online checkout is not active yet. Paid trials are provisioned through the AthleteN subscription record until server-side billing is enabled.</p></div></div></section></FeaturePage>; }
function VerificationPage({ rows, openForm }: { rows: VerificationRequest[]; openForm: (resource: Resource) => void }) { return <FeaturePage title="Student verification" actions={<button className="btn primary" onClick={() => openForm("verifications")}><Plus size={16} /> Submit proof</button>}><section className="card panel"><h3>Accepted proof</h3><p>Upload a school ID, fee receipt, or bonafide certificate. Admins review submissions and approve verified athlete access.</p><DataTable rows={rows} empty="No verification requests submitted" columns={[{ key: "document_type", label: "Proof type" },{ key: "status", label: "Status" },{ key: "reviewer_notes", label: "Reviewer notes" }]} /></section></FeaturePage>; }
function AiCoach({ usage, accessToken, setToast }: { usage: UsageSummary; accessToken?: string; setToast: (toast: ToastState) => void }) { const [topic,setTopic]=useState("Training Coach"); const [prompt,setPrompt]=useState(""); const [answer,setAnswer]=useState(""); const [loading,setLoading]=useState(false); const remaining=Math.max(0,usage.limit-usage.used); async function ask(){ if(!prompt.trim()){setToast({type:"warning",message:"Enter a training question before asking AI Coach."});return;} if(!usage.limit){setToast({type:"error",message:"AI Coach is not available on the Free plan. Upgrade to an eligible plan to use AI."});return;} if(remaining<=0){setToast({type:"error",message:"Monthly AI limit reached for your current plan."});return;} if(!accessToken){setToast({type:"error",message:"Please sign in again before using AI Coach."});return;} setLoading(true);setAnswer("");try{const response=await fetch("/.netlify/functions/ai-coach",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${accessToken}`},body:JSON.stringify({topic,prompt})});const payload=await response.json() as {answer?:string;error?:string};if(!response.ok)throw new Error(payload.error||"AI request failed.");setAnswer(payload.answer??"");}catch(error){setToast({type:"error",message:error instanceof Error?error.message:"AI request failed."});}finally{setLoading(false);}} return <FeaturePage title="Secure AI Coach"><section className="card panel ai-panel"><div className="usage-bar"><span>Monthly AI usage</span><strong>{usage.used}/{usage.limit}</strong><i style={{width:`${usage.limit?Math.min(100,(usage.used/usage.limit)*100):0}%`}} /></div>{!usage.limit&&<p className="notice" role="status">Free plan includes zero AI access. AI requests are also blocked on the server before OpenAI is called.</p>}<select value={topic} onChange={(e)=>setTopic(e.target.value)} aria-label="AI coaching topic">{["Training Coach","Tournament Preparation","Match Analysis","Nutrition Advice","Recovery Advice","Goal Suggestions","Performance Reports","Motivational Feedback"].map((item)=><option key={item}>{item}</option>)}</select><textarea value={prompt} onChange={(e)=>setPrompt(e.target.value)} placeholder="Describe your goal, recent training, opponent, recovery issue, or tournament situation." /><button className="btn primary" onClick={ask} disabled={loading||remaining<=0||!usage.limit}>{loading?"Thinking...":"Ask AI Coach"}</button>{answer&&<div className="answer">{answer}</div>}</section></FeaturePage>; }
function DocumentsPage({ rows, openForm, openDocument, removeDocument }: { rows: DocumentRecord[]; openForm: (resource: Resource) => void; openDocument: (document: DocumentRecord) => Promise<void>; removeDocument: (document: DocumentRecord) => Promise<void> }) { return <FeaturePage title="Secure Documents" actions={<button className="btn primary" onClick={()=>openForm("documents")}><Upload size={16}/> Add document</button>}><section className="card panel"><p>Upload private athlete documents to Supabase Storage. Files are stored under your user folder and protected by Storage RLS.</p><DataTable rows={rows} empty="No documents yet" columns={[{key:"title",label:"Document"},{key:"document_type",label:"Type"},{key:"issued_at",label:"Issued"},{key:"expires_at",label:"Expiry"},{key:"status",label:"Status",render:(row)=>{const status=documentStatus(row.expires_at);return <span className={`status-chip ${status.tone}`}>{status.label}</span>;}},{key:"actions",label:"",render:(row)=><div className="inline-actions"><button className="plain" onClick={()=>void openDocument(row)} disabled={!row.file_path}><Download size={14}/> Open</button><button className="plain danger" onClick={()=>void removeDocument(row)}><Trash2 size={14}/> Delete</button></div>}]} /></section></FeaturePage>; }
function RoadmapPage({ rows, vote, isAdmin, openForm, updateStatus, removeItem }: { rows: RoadmapItem[]; vote: (item: RoadmapItem)=>Promise<void>; isAdmin: boolean; openForm:(resource:Resource)=>void; updateStatus:(item:RoadmapItem,status:string)=>Promise<void>; removeItem:(item:RoadmapItem)=>Promise<void> }) { return <FeaturePage title="Public roadmap" actions={isAdmin?<button className="btn primary" onClick={()=>openForm("roadmap")}><Plus size={16}/> Add roadmap item</button>:undefined}><section className="card panel"><p>Votes are stored in Supabase. Each authenticated user can vote once per feature; totals are maintained by the database. Admin-only controls are protected by RLS.</p><DataTable rows={rows} empty="Roadmap is being prepared" columns={[{key:"title",label:"Feature"},{key:"status",label:"Status",render:(row)=>isAdmin?<select value={row.status||"planned"} onChange={(event)=>void updateStatus(row,event.target.value)} aria-label={`Update ${row.title} status`}>{["research","planned","in-progress","released"].map((status)=><option key={status} value={status}>{status}</option>)}</select>:row.status},{key:"votes",label:"Votes"},{key:"vote",label:"",render:(row)=><div className="inline-actions"><button className="btn" disabled={row.user_has_voted} onClick={()=>void vote(row)}>{row.user_has_voted?"Voted":"Vote"}</button>{isAdmin&&<button className="plain danger" onClick={()=>void removeItem(row)}>Delete</button>}</div>}]} /></section></FeaturePage>; }
function AdminPage({ data }: { data: CloudData }) { return <><AdminControlCenter userId={data.profile.user_id || "unknown"} role={data.profile.role || "athlete"} /><MessageReportsPanel /></>; }
function OnboardingPage({ profile, saveProfile }: { profile: Profile; saveProfile: (values: Partial<Profile>)=>Promise<void> }) { const [values,setValues]=useState<Partial<Profile>>({full_name:profile.full_name||"",username:profile.username||"",date_of_birth:profile.date_of_birth||"",gender:profile.gender||"",sport:"taekwondo",discipline:profile.discipline,academy:profile.academy||"",coach:profile.coach||""}); const [saving,setSaving]=useState(false); const [error,setError]=useState(""); async function submit(event:React.FormEvent){event.preventDefault();setError("");if(!values.full_name?.trim()||!values.date_of_birth||!values.gender||values.sport!=="taekwondo"||!values.discipline||!values.academy?.trim()||!values.coach?.trim()){setError("Name, DOB, gender, Taekwondo, discipline, club, and coach are required.");return;}setSaving(true);try{await saveProfile(values);}catch(saveError){setError(saveError instanceof Error?saveError.message:"Profile could not be saved. Please try again.");}finally{setSaving(false);}} return <main className="onboarding-page"><section className="auth-card"><span className="eyebrow">First setup</span><h1>Set up your Taekwondo profile</h1><p>Taekwondo is currently the implemented sport. Choose your discipline explicitly so Kyorugi and Poomsae data never get mixed.</p><form onSubmit={submit}><Field label="Name" value={values.full_name||""} onChange={(event)=>setValues({...values,full_name:event.target.value})} required/><Field label="Username" value={String(values.username||"")} onChange={(event)=>setValues({...values,username:event.target.value.toLowerCase()})} maxLength={30} required/><Field label="Date of birth" type="date" value={String(values.date_of_birth||"")} onChange={(event)=>setValues({...values,date_of_birth:event.target.value})} max={new Date().toISOString().slice(0,10)} required/><SelectField label="Gender" value={values.gender||""} onChange={(event)=>setValues({...values,gender:event.target.value})} required><option value="">Select</option><option value="male">Male</option><option value="female">Female</option><option value="other">Other</option><option value="prefer_not_to_say">Prefer not to say</option></SelectField><SelectField label="Sport" value="taekwondo" disabled><option value="taekwondo">Taekwondo</option></SelectField><SelectField label="Discipline" value={values.discipline||""} onChange={(event)=>setValues({...values,discipline:event.target.value as "kyorugi"|"poomsae"})} required><option value="">Choose your discipline</option><option value="kyorugi">Kyorugi</option><option value="poomsae">Poomsae</option></SelectField><Field label="Club" value={values.academy||""} onChange={(event)=>setValues({...values,academy:event.target.value})} placeholder="Club / independent athlete" required/><Field label="Coach" value={values.coach||""} onChange={(event)=>setValues({...values,coach:event.target.value})} placeholder="Coach / not connected yet" required/><button className="btn primary" disabled={saving}>{saving?"Saving…":"Save and continue"}</button></form>{error&&<p className="notice" role="alert">{error}</p>}</section></main>; }
function AppShell() { const auth=useAuth(); const userId=auth.user?.id; const [page,setPage]=useState<PageId>(()=>pageFromPath()); const [toast,setToast]=useState<ToastState>(null); const {data,loading,refresh,hasProfile}=useCloudData(auth.user?.id,setToast); const [form,setForm]=useState<{resource:Resource;values:Record<string,string|number|boolean>}|null>(null); const isAdmin=isAdminProfile(data.profile); const roleWorkspace=data.profile.role === "coach" || data.profile.plan_id === "champion" ? "coach" : data.profile.role === "academy_admin" || data.profile.plan_id === "academy" ? "academy" : "athlete"; const visibleNav=useMemo(()=>{ const base=nav.filter(([id])=>id!=="admin"||isAdmin); if(roleWorkspace==="coach") return base.filter(([id])=>["dashboard","taekwondo","messages","profile","plans"].includes(id)); if(roleWorkspace==="academy") return base.filter(([id])=>["dashboard","taekwondo","messages","profile","plans"].includes(id)); return base; },[isAdmin,roleWorkspace]); useEffect(()=>{if(loading)return;if(!hasProfile&&window.location.pathname!=="/onboarding")window.history.replaceState(null,"","/onboarding");else if(hasProfile&&window.location.pathname==="/onboarding")window.history.replaceState(null,"","/");},[loading,hasProfile]); useEffect(()=>{const syncPath=()=>setPage(pageFromPath());window.addEventListener("popstate",syncPath);return()=>window.removeEventListener("popstate",syncPath);},[]); useEffect(()=>{if(!userId||!supabase||!isSupabaseConfigured)return undefined;void registerDesktopNotifications();const channel=supabase.channel(`athleten-${userId}`).on("postgres_changes",{event:"*",schema:"public",table:"profiles",filter:`user_id=eq.${userId}`},()=>{void refresh();}).on("postgres_changes",{event:"*",schema:"public",table:"age_verifications",filter:`user_id=eq.${userId}`},()=>{void refresh();}).on("postgres_changes",{event:"INSERT",schema:"public",table:"notifications",filter:`user_id=eq.${userId}`},(payload)=>{const row=payload.new as {title?:string;body?:string;id?:string};void showDesktopNotification({title:row.title||"AthleteN notification",body:row.body||"You have a new notification in AthleteN.",tag:`athleten-${row.id||Date.now()}`,url:"/"});}).subscribe();return()=>{void supabase.removeChannel(channel);};},[userId]); const current=useMemo(()=>visibleNav.find(([id])=>id===page),[page,visibleNav]); const pageTitle=current?.[1]||(page==="admin"?"Admin Panel":"Dashboard"); const plan=getPlan(data.profile.plan_id||"free"); const usage:UsageSummary={used:data.aiUsage.length,limit:plan.aiLimit,plan}; async function save(resource:Resource,values:Record<string,string|number|boolean>,options:{rethrow?:boolean}={}){try{const user_id=auth.user?.id;if(!user_id&&resource!=="roadmap")throw new Error("You must be logged in.");if(resource==="training"&&(!values.title||!values.session_date||!values.minutes))throw new Error("Training title, date, and minutes are required.");if(resource==="tournaments"&&!values.name)throw new Error("Tournament name is required.");if(resource==="medals"&&(!values.event_name||!values.medal_type))throw new Error("Event and medal type are required.");if(resource==="weights"&&(!values.logged_at||!values.weight_kg))throw new Error("Weight date and value are required.");if(resource==="documents"&&(!values.title||!values.document_type||!values.file_path))throw new Error("Document name, type, and file are required.");if(resource==="verifications"&&(!values.document_type||!values.file_path))throw new Error("Proof type and proof file are required.");if(resource==="feedback"&&!values.title)throw new Error("Feedback title is required.");if(resource==="checklist"&&(!values.item||!values.category))throw new Error("Checklist item and category are required.");if(resource==="calendar"&&(!values.title||!values.event_type||!values.event_date))throw new Error("Calendar title, type, and date are required.");if(resource==="roadmap"&&(!isAdmin||!values.title))throw new Error(isAdmin?"Roadmap title is required.":"Admin access required.");if(resource==="profile"){const safeValues=sanitizeProfileValues(values as Partial<Profile>);await upsertRow("profile",{...safeValues,user_id},{onConflict:"user_id"});}else if(resource==="roadmap")await insertRow(resource,values);else await insertRow(resource,resource==="feedback"?{...values,visibility:values.visibility||"public",user_id}:{...values,user_id});setToast({type:"success",message:"Saved securely in Supabase."});setForm(null);try{await refresh();}catch{setToast({type:"warning",message:"Saved profile, but some dashboard data could not be refreshed."});}}catch(error){setToast({type:"error",message:error instanceof Error?error.message:"Save failed."});if(options.rethrow)throw error;}} async function openDocument(document:DocumentRecord){if(!document.file_path){setToast({type:"warning",message:"This document has metadata but no uploaded file yet."});return;}try{const signedUrl=await createSignedFileUrl("documents",document.file_path);window.open(signedUrl,"_blank","noopener,noreferrer");}catch(error){setToast({type:"error",message:error instanceof Error?error.message:"Unable to open document."});}} async function removeDocument(document:DocumentRecord){try{if(document.file_path)await deletePrivateFile("documents",document.file_path);await remove("documents",document.id);}catch(error){setToast({type:"error",message:error instanceof Error?error.message:"Unable to delete document."});}} async function voteRoadmap(item:RoadmapItem){if(!item.id||!auth.user?.id){setToast({type:"error",message:"Please sign in before voting."});return;}try{await insertRow("roadmapVotes",{roadmap_item_id:item.id,user_id:auth.user.id});setToast({type:"success",message:"Vote recorded."});await refresh();}catch(error){const message=error instanceof Error?error.message:"";setToast({type:"warning",message:message.toLowerCase().includes("duplicate")?"You have already voted for this feature.":"Vote could not be recorded."});}} async function saveProfile(values:Partial<Profile>){await save("profile",values as Record<string,string|number|boolean>,{rethrow:true});} async function remove(resource:Resource,id?:string){if(!id)return;try{await deleteRow(resource,id,auth.user?.id);setToast({type:"success",message:"Deleted."});await refresh();}catch(error){setToast({type:"error",message:error instanceof Error?error.message:"Delete failed."});}} function navigate(id:PageId){setPage(id);window.history.pushState(null,"",id==="dashboard"?"/":`/${id}`);} async function updateRoadmapStatus(item:RoadmapItem,status:string){if(!item.id||!isAdmin)return;try{await updateRow("roadmap",item.id,{status});setToast({type:"success",message:"Roadmap status updated."});await refresh();}catch(error){setToast({type:"error",message:error instanceof Error?error.message:"Roadmap status could not be updated."});}} async function removeRoadmapItem(item:RoadmapItem){if(!item.id||!isAdmin)return;try{await deleteRow("roadmap",item.id);setToast({type:"success",message:"Roadmap item deleted."});await refresh();}catch(error){setToast({type:"error",message:error instanceof Error?error.message:"Roadmap item could not be deleted."});}} function openForm(resource:Resource){setForm({resource,values:{}});} let content:React.ReactNode=null; if(loading)content=<div className="skeleton card">Join the future</div>; else if(!hasProfile)return <OnboardingPage profile={data.profile} saveProfile={saveProfile}/>; else if(page==="dashboard") { const role = data.profile.role; const planId = data.profile.plan_id; if(role === "coach" || planId === "champion") content=<CoachDashboard profile={data.profile} userId={userId} setToast={setToast}/>; else if(role === "academy_admin" || planId === "academy") content=<AcademyDashboard profile={data.profile} userId={userId} setToast={setToast}/>; else content=<Dashboard data={data} usage={usage} openForm={openForm}/>; } else if(page==="taekwondo")content=<TaekwondoHub profile={data.profile} kyorugiBouts={data.kyorugiBouts||[]} poomsaePerformances={data.poomsaePerformances||[]} taekwondoTraining={data.taekwondoTraining||[]} setToast={setToast} refresh={refresh}/>; else if(page==="profile")content=<FeaturePage title="Athlete Profile" actions={<button className="btn primary" onClick={()=>openForm("profile")}><User size={16}/> Edit profile</button>}><ProfileIdentityCard profile={data.profile} userId={userId} onSaved={refresh} onToast={setToast}/><section className="card panel profile-grid"><div><h3>Profile details</h3><p><strong>Username:</strong> {data.profile.username?`@${data.profile.username}`:"Not set"}</p><p>{data.profile.belt||"Belt not set"} · {data.profile.academy||"Academy not set"}</p><p>Coach: {data.profile.coach||"Not set"}</p><p>Emergency: {data.profile.emergency_contact||"Not set"}</p></div></section></FeaturePage>; else if(page==="plans")content=<PlansPage profile={data.profile} userId={userId} onSaved={refresh} onToast={setToast}/>; else if(page==="verification")content=<VerificationPage rows={data.verifications} openForm={openForm}/>; else if(page==="tournaments")content=<FeaturePage title="Tournaments" actions={<button className="btn primary" onClick={()=>openForm("tournaments")}><Plus size={16}/> Add</button>}><DataTable rows={data.tournaments} empty="No tournaments yet" columns={[{key:"name",label:"Tournament"},{key:"starts_at",label:"Date"},{key:"location",label:"Location"},{key:"status",label:"Status"},{key:"remove",label:"",render:(row)=><button className="plain danger" onClick={()=>remove("tournaments",row.id)}>Delete</button>}]}/></FeaturePage>; else if(page==="training")content=<FeaturePage title="Training Sessions" actions={<button className="btn primary" onClick={()=>openForm("training")}><Plus size={16}/> Log</button>}><DataTable rows={data.training} empty="No training sessions yet" columns={[{key:"title",label:"Session"},{key:"session_date",label:"Date"},{key:"minutes",label:"Minutes"},{key:"intensity",label:"Intensity"}]}/></FeaturePage>; else if(page==="medals")content=<FeaturePage title="Medals" actions={<button className="btn primary" onClick={()=>openForm("medals")}><Plus size={16}/> Add</button>}><DataTable rows={data.medals} empty="No medals yet" columns={[{key:"event_name",label:"Event"},{key:"medal_type",label:"Medal"},{key:"category",label:"Category"},{key:"awarded_at",label:"Date"}]}/></FeaturePage>; else if(page==="documents")content=<DocumentsPage rows={data.documents} openForm={openForm} openDocument={openDocument} removeDocument={removeDocument}/>; else if(page==="weight")content=<FeaturePage title="Weight Tracker" actions={<button className="btn primary" onClick={()=>openForm("weights")}><Plus size={16}/> Log</button>}><section className="card panel"><ResponsiveContainer width="100%" height={320}><LineChart data={data.weights}><CartesianGrid strokeDasharray="3 3" stroke="#25405f"/><XAxis dataKey="logged_at"/><YAxis/><Tooltip/><Line type="monotone" dataKey="weight_kg" stroke="#52ddac" strokeWidth={3}/></LineChart></ResponsiveContainer></section></FeaturePage>; else if(page==="calendar")content=<FeaturePage title="Calendar"><DataTable rows={data.training.map((item)=>({...item,event_type:"training"})).concat(data.tournaments.map((item)=>({id:item.id,title:item.name,session_date:item.starts_at||"",event_type:"competition",minutes:0})))} empty="No calendar events" columns={[{key:"title",label:"Event"},{key:"session_date",label:"Date"},{key:"event_type",label:"Type"}]}/></FeaturePage>; else if(page==="checklist")content=<FeaturePage title="Competition Checklist" actions={<button className="btn primary" onClick={()=>openForm("checklist")}><Plus size={16}/> Add</button>}><section className="card checklist">{data.checklist.map((item)=><label key={item.id||item.item}><input type="checkbox" checked={Boolean(item.completed)} readOnly/> {item.item}<span>{item.category}</span></label>)}</section></FeaturePage>; else if(page==="scanner")content=<InstagramOrganizerScanner accessToken={auth.session?.access_token} setToast={setToast}/>; else if(page==="ai")content=<AiCoachReliable usage={usage} accessToken={auth.session?.access_token} setToast={setToast}/>; else if(page==="feedback")content=<FeaturePage title="Feedback portal" actions={<button className="btn primary" onClick={()=>openForm("feedback")}><Plus size={16}/> Submit feedback</button>}><DataTable rows={data.feedback} empty="No feedback yet" columns={[{key:"title",label:"Title"},{key:"status",label:"Status"},{key:"priority",label:"Priority"}]}/></FeaturePage>; else if(page==="roadmap")content=<RoadmapPage rows={data.roadmap} vote={voteRoadmap} isAdmin={isAdmin} openForm={openForm} updateStatus={updateRoadmapStatus} removeItem={removeRoadmapItem}/>; else if(page==="messages")content=<MessagingPage/>; else if(page==="admin")content=isAdmin?<AdminPage data={data}/>:<FeaturePage title="Access denied"><section className="card panel"><h3>Admin access required</h3><p>Your account is not authorized to view admin operations.</p><button className="btn" onClick={()=>navigate("dashboard")}>Back to dashboard</button></section></FeaturePage>; return <div className="app-shell"><aside className="sidebar"><div className="brand"><Shield/><span>AthleteN</span></div><p className="edition">Taekwondo Edition V2</p><nav>{visibleNav.map(([id,label,Icon])=><button key={id} className={id===page?"active":""} onClick={()=>navigate(id)}><Icon size={18}/> {label}</button>)}</nav><button className="logout" onClick={auth.signOut}><LogOut size={16}/> Logout</button></aside><main><header><div><p className="eyebrow">Nova Code Cloud</p><h1>{pageTitle}</h1></div><button className="icon-btn" aria-label="Enable laptop notifications" title={desktopNotificationPermission()==="granted"?"Laptop notifications enabled":"Enable laptop notifications"} onClick={async()=>{const permission=await requestDesktopNotifications();if(permission==="granted")setToast(null);else if(permission==="denied")setToast({type:"error",message:"Laptop notifications are blocked. Allow notifications for AthleteN in your browser settings."});else if(permission==="unsupported")setToast({type:"error",message:"Laptop notifications are not supported by this browser."});}}><Bell size={18}/></button></header>{!auth.emailVerified&&<div className="card panel verify-banner"><BadgeCheck/><span>Please verify your email to unlock full account trust features.</span></div>}<AgeVerificationGate profile={data.profile} refresh={refresh}>{content}</AgeVerificationGate><footer>Copyright © 2026 Nova Code</footer></main><Toast toast={toast} onClear={() => setToast(null)}/>{form&&<RecordModal form={form} setForm={setForm} save={save} profile={data.profile} userId={auth.user?.id} setToast={setToast}/>}</div>; }
type RecordModalProps = { form:{resource:Resource;values:Record<string,string|number|boolean>}; setForm:React.Dispatch<React.SetStateAction<{resource:Resource;values:Record<string,string|number|boolean>}|null>>; save:(resource:Resource,values:Record<string,string|number|boolean>,options?:{rethrow?:boolean})=>Promise<void>; profile:Profile; userId?:string; setToast:(toast:ToastState)=>void; };
function RecordModal({ form, setForm, save, profile, userId, setToast }: RecordModalProps) { const [values,setValues]=useState<Record<string,string|number|boolean>>(form.resource==="profile"?profile as Record<string,string|number|boolean>:{}); const requiredFields=new Set(form.resource==="profile"?["full_name"]:form.resource==="tournaments"?["name"]:form.resource==="training"?["title","session_date","minutes"]:form.resource==="medals"?["event_name","medal_type"]:form.resource==="weights"?["logged_at","weight_kg"]:form.resource==="checklist"?["item","category"]:form.resource==="feedback"?["title"]:form.resource==="roadmap"?["title"]:form.resource==="verifications"?["document_type"]:form.resource==="documents"?["title","document_type"]:form.resource==="calendar"?["title","event_type","event_date"]:[]); const [file,setFile]=useState<File|null>(null); const [saving,setSaving]=useState(false); const fields:Array<[string,string,string?,string[]?]>=(({profile:[["full_name","Name"],["username","Username"],["date_of_birth","Date of birth","date"],["weight_kg","Weight","number"],["height_cm","Height","number"],["belt","Belt"],["academy","Academy"],["coach","Coach"],["emergency_contact","Emergency contact"]],tournaments:[["name","Tournament"],["starts_at","Date","date"],["location","Location"],["status","Status"],["opponent_notes","Opponent notes"],["match_notes","Match notes"]],training:[["title","Session"],["session_date","Date","date"],["minutes","Minutes","number"],["intensity","Intensity"]],medals:[["event_name","Event"],["medal_type","Medal"],["category","Category"],["awarded_at","Date","date"]],documents:[["title","Document name"],["document_type","Type"],["issued_at","Issue date","date"],["expires_at","Expiry date","date"],["notes","Notes"]],weights:[["logged_at","Date","date"],["weight_kg","Weight","number"],["target_weight_kg","Target","number"]],calendar:[["title","Event"],["event_date","Date"],["event_type","Type"],["reminder_at","Reminder","datetime-local"]],checklist:[["item","Item"],["category","Category"]],feedback:[["title","Title"],["details","Details"],["priority","Priority","select",["low","normal","high"]],["visibility","Visibility","select",["public","private"]]],roadmap:[["title","Feature"],["description","Description"],["status","Status","select",["research","planned","in-progress","released"]]],verifications:[["document_type","Proof type","select",["school_id","fee_receipt","bonafide"]]]}) as Partial<Record<Resource,Array<[string,string,string?,string[]?]>>>)[form.resource]||[]; async function submit(event:React.FormEvent){event.preventDefault();setSaving(true);let uploadedPath:string|undefined;try{const payload={...values};if(form.resource==="verifications"||form.resource==="documents"){if(!file)throw new Error(form.resource==="verifications"?"Choose a proof file before submitting.":"Choose a document file before saving.");if(!userId)throw new Error("Please sign in again before uploading.");const extension=file.name.includes(".")?file.name.split(".").pop()?.toLowerCase():undefined;const allowedExtensions=["pdf","png","jpg","jpeg","webp"];if(!extension||!allowedExtensions.includes(extension))throw new Error("Choose a PDF, PNG, JPG, JPEG, or WEBP file.");const safeName=`${crypto.randomUUID()}.${extension}`;const bucket=form.resource==="verifications"?"verification-proofs":"documents";uploadedPath=await uploadPrivateFile(bucket,`${userId}/${safeName}`,file);payload.file_path=uploadedPath;}if(form.resource==="verifications"){if(!payload.document_type)throw new Error("Choose the proof type.");payload.status="pending";}if(form.resource==="training"&&Number(payload.minutes)<=0)throw new Error("Training minutes must be greater than zero.");if(form.resource==="weights"&&Number(payload.weight_kg)<=0)throw new Error("Weight must be greater than zero.");await save(form.resource,payload,{rethrow:true});}catch(error){if(uploadedPath)await deletePrivateFile(form.resource==="verifications"?"verification-proofs":"documents",uploadedPath).catch(()=>undefined);setToast({type:"error",message:error instanceof Error?error.message:"Save failed."});}finally{setSaving(false);}} return <div className="modal-backdrop"><form className="modal" onSubmit={(event)=>{void submit(event);}}><button type="button" className="close" onClick={()=>setForm(null)} aria-label="Close">x</button><h2>{form.resource}</h2>{fields.map(([name,label,type="text",options])=>options?<SelectField key={name} label={label} value={String(values[name]||"")} onChange={(event)=>setValues({...values,[name]:event.target.value})}><option value="">Select</option>{options.map((option)=><option key={option} value={option}>{option}</option>)}</SelectField>:<Field key={name} label={label} required={requiredFields.has(name)} type={type} value={String(values[name]||"")} onChange={(event)=>setValues({...values,[name]:type==="number"?Number(event.target.value):event.target.value})}/>) }{(form.resource==="documents"||form.resource==="verifications")&&<label className="field"><span>{form.resource==="verifications"?"Proof file":"Upload file"}</span><input type="file" accept=".pdf,.png,.jpg,.jpeg,.webp" required onChange={(event)=>setFile(event.target.files?.[0]||null)}/></label>}<button className="btn primary" disabled={saving}>{saving?"Saving...":"Save"}</button></form></div>; }
function ProtectedApp(){const auth=useAuth();if(auth.loading)return <main className="auth-page"><section className="auth-card">Join the future</section></main>;if(window.location.pathname==="/parent-approval")return <ParentApprovalPage/>;if(isAuthCallbackRoute())return <VerificationCallback/>;if(isPasswordResetRoute())return <AuthScreen initialMode="reset"/>;if(auth.profileBootstrapError)return <main className="auth-page"><section className="auth-card"><span className="eyebrow">AthleteN security</span><h1>Account setup could not be completed</h1><p>Your secure profile could not be initialized, so AthleteN has stopped before loading account data.</p><p className="notice" role="alert">{auth.profileBootstrapError}</p><button className="btn primary" onClick={()=>window.location.reload()}>Retry</button></section></main>;return auth.user?<AppShell/>:<AuthScreen/>;}
createRoot(document.getElementById("root") as HTMLElement).render(<AuthProvider><ProtectedApp/></AuthProvider>);
